// Usage: node tools/gen-api/gen.mjs <openapi.json> <out.ts>
import { readFileSync, writeFileSync } from "node:fs";
import { pathToFileURL } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const BANNER =
  "// Generated by `pnpm run gen:api` from src/lib/openapi.json. Do not edit by hand.\n\n";

/** The TypeScript source for an OpenAPI schema file, exactly as it is committed. */
export async function generate(schemaPath) {
  const schema = JSON.parse(readFileSync(schemaPath, "utf8"));
  // A request field with a default may be left out, so only the schema's `required` list
  // decides what is optional; response models mark their defaulted fields required.
  return BANNER + astToString(await openapiTS(schema, { defaultNonNullable: false }));
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const [schemaPath, outPath] = process.argv.slice(2);
  writeFileSync(outPath, await generate(schemaPath));
}
